from pathlib import Path
import json
p=Path(__file__).parent
engine=(p/'wzw-engine.js').read_text()
data=(p/'preview-data.js').read_text()
html='''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WzW · Architectural Atlas v2</title><style>*{box-sizing:border-box}html,body{margin:0;height:100%;background:#241b15;color:#eadabd;font-family:Georgia,serif}.review{height:58px;display:flex;align-items:center;justify-content:space-between;padding:0 18px;gap:16px;border-bottom:1px solid #80684b}.review strong{font-size:14px;font-weight:400;letter-spacing:1px}.review small{display:block;font:9px Arial,sans-serif;letter-spacing:1.4px;color:#baa17c;margin-top:5px}nav{display:flex;gap:5px}nav button{font:12px Georgia,serif;color:#d8c5a5;padding:8px 13px;border:1px solid #826b4c;background:transparent;cursor:pointer}nav button.active{background:#e8d7b4;color:#473320}iframe{border:0;width:100%;height:calc(100% - 58px);display:block}@media(max-width:700px){.review{height:99px;display:block;padding:9px}nav{margin-top:9px;overflow:auto}nav button{white-space:nowrap;padding:7px}iframe{height:calc(100% - 99px)}}</style></head><body><div class="review"><div><strong>WzW · Architectural Atlas / 02</strong><small>DỮ LIỆU MẪU · KHÔNG PHẢI TRẠNG THÁI RP</small></div><nav aria-label="Cảnh mẫu"><button data-scene="grounds">Khuôn viên</button><button data-scene="floor">Hầm ngục</button><button data-scene="tower">Tháp</button><button data-scene="street">Phố làng</button><button data-scene="interior">Đại Sảnh</button></nav></div><iframe id="preview" title="Bản đồ WzW"></iframe><script>'''+data+'\nconst ENGINE='+json.dumps(engine,ensure_ascii=False).replace('</','<\\/')+''';
function show(k){if(!WZW_PREVIEWS[k])k='floor';document.querySelectorAll('[data-scene]').forEach(b=>b.classList.toggle('active',b.dataset.scene===k));const frame=document.getElementById('preview');frame.srcdoc='<!doctype html><html lang="vi"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>WzW Map</title><div id="wzw-map-root"></div><script>window.MAP_DATA='+JSON.stringify(WZW_PREVIEWS[k]).replace(/</g,String.fromCharCode(92)+'u003c')+';<\\/script><script>'+ENGINE.replace(/<\\/script/gi,'<\\\\/script')+'<\\/script></html>';history.replaceState(null,'','#'+k);}
document.querySelectorAll('[data-scene]').forEach(b=>b.onclick=()=>show(b.dataset.scene));show(location.hash.slice(1)||'floor');</script></body></html>'''
(p/'index.html').write_text(html)
